SELECT id, session_id, user_id, last_read_message_id, last_read_time, unread_count, create_time
FROM chat_session_user
WHERE session_id = #{sessionId}
  AND user_id = #{userId}
LIMIT 1

SELECT id, session_id, user_id, last_read_message_id, last_read_time, unread_count, create_time
FROM chat_session_user
WHERE session_id = #{sessionId}
  AND user_id != #{userId}
ORDER BY id ASC
LIMIT 1
